/// <summary>
/// The class <c>GUPTableFieldAttribute</c> is used for tagging <c>PricingAttributeSource</c>.
/// </summary>
public class GUPPricingAttributeFieldsDiscoveryAttribute extends SysAttribute implements SysExtensionIAttribute
{
    public str fieldName;
    public str allowedValueAlternativeTableName;
    public str allowedValueAlternativeFieldName;

}

Method.Source:
public void new(str _fieldName, 
    str _allowedValueAlternativeTableName = "",
    str _allowedValueAlternativeFieldName = "")
{
    this.fieldName = _fieldName;
    this.allowedValueAlternativeTableName = _allowedValueAlternativeTableName;
    this.allowedValueAlternativeFieldName = _allowedValueAlternativeFieldName;
}
